<script>
document.querySelectorAll('[data-export-builder]').forEach(root=>{
 root.querySelectorAll('form').forEach(form=>form.addEventListener('submit',()=>{const target=form.querySelector('[name=selected_records]');if(target)target.value=JSON.stringify(Array.from(form.querySelectorAll('[data-export-record]:checked')).map(box=>box.value));}));
 root.querySelectorAll('[data-export-check]').forEach(button=>button.addEventListener('click',()=>{const scope=button.closest('[data-export-scope]');scope.querySelectorAll('input[type=checkbox]').forEach(box=>box.checked=button.dataset.exportCheck==='all');const selected=scope.querySelector('input[type=radio][value=selected]');if(selected)selected.checked=true;}));
 root.querySelectorAll('[data-export-item] input[type=checkbox]').forEach(box=>box.addEventListener('change',()=>{const scope=box.closest('[data-export-scope]');const selected=scope?.querySelector('input[type=radio][value=selected]');if(selected)selected.checked=true;}));
 root.querySelectorAll('[data-export-search]').forEach(search=>search.addEventListener('input',()=>{const needle=search.value.toLocaleLowerCase();search.closest('[data-export-scope]').querySelectorAll('[data-export-item]').forEach(item=>item.hidden=!item.textContent.toLocaleLowerCase().includes(needle));}));
});
</script>
